/**
 * Orbit 2 — Project → Internal Request (client request, 19 Oct 2026).
 *
 * Requests from one office department to another, logged and tracked with the
 * same split screen as the Project List:
 *
 *   Left   scrollable table of every request, searchable, status editable inline
 *   Right  the selected request in full, or a fresh entry form
 *
 * Task IDs (INTREQ-26-00001) are generated by the database on insert
 * (orbit2_assign_intreq_task_id). Office-only — there is no field-app side.
 *
 * Loads its own rows rather than going through useOrbit2: nothing else in
 * Orbit 2 reads internal requests, so the shared load stays as it is.
 */
import { useCallback, useEffect, useMemo, useState } from "react";
import { Loader2, Plus, Search, Trash2 } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { errorMessage } from "@/lib/error-message";
import { fmtDMY } from "@/lib/format-date";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/lib/auth";
import { suggestionsFor } from "./orbit2-data";
import { useOrbit2Identity } from "./orbit2-identity";
import { Field, inputCls, Typeahead, TeamPicker, stamp } from "./orbit2-fields";

const sb = supabase as any;

export const INTREQ_DEPARTMENTS = [
  "Logistic", "Operation", "Admin", "Managers", "Port Agency", "Crewcare", "HR",
  "Warehouse", "Waypoint", "Accounts", "Provisioning", "IT", "Marketing",
] as const;

export const INTREQ_STATUSES = ["Assigned", "On-going", "Completed"] as const;

/** Assigned = sky, On-going = amber, Completed = emerald. */
const INTREQ_STATUS_COLOR: Record<string, string> = {
  Assigned: "#0EA5E9",
  "On-going": "#F59E0B",
  Completed: "#10B981",
};
const intreqColor = (s: string) => INTREQ_STATUS_COLOR[s] ?? "#4A7090";

export type Orbit2InternalRequest = {
  id: string;
  task_id: string;
  department: string;
  status: string;
  description: string;
  assigned_team: string[];
  requestor_name: string | null;
  request_date: string | null;
  location: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
};

type Draft = Partial<Orbit2InternalRequest> & { assigned_team: string[] };

/** Today as YYYY-MM-DD on the viewer's own calendar (not UTC). */
function today(): string {
  const d = new Date();
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

const emptyDraft = (requestor: string): Draft => ({
  status: "Assigned",
  department: "",
  description: "",
  assigned_team: [],
  requestor_name: requestor,
  request_date: today(),
  location: "",
});

export function Orbit2InternalRequests() {
  const { user } = useAuth();
  const identity = useOrbit2Identity();

  const [rows, setRows] = useState<Orbit2InternalRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [draft, setDraft] = useState<Draft>(emptyDraft(""));
  const [saving, setSaving] = useState(false);

  const reload = useCallback(async () => {
    const { data, error } = await sb
      .from("orbit2_internal_requests")
      .select("*")
      .order("created_at", { ascending: false });
    if (error) toast.error(errorMessage(error, "Could not load internal requests"));
    else setRows((data ?? []) as Orbit2InternalRequest[]);
    setLoading(false);
  }, []);

  useEffect(() => { void reload(); }, [reload]);

  // The signed-in name arrives a moment after the page — fill an empty
  // Requestor on a new request once it does.
  useEffect(() => {
    if (!creating || !identity.name) return;
    setDraft((d) => (d.requestor_name ? d : { ...d, requestor_name: identity.name }));
  }, [identity.name, creating]);

  const locationOptions = useMemo(() => suggestionsFor(rows.map((r) => r.location)), [rows]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return rows;
    return rows.filter((r) =>
      [r.task_id, r.department, r.status, r.description, r.requestor_name, r.location,
       fmtDMY(r.request_date), (r.assigned_team ?? []).join(" ")]
        .some((v) => (v ?? "").toLowerCase().includes(q)));
  }, [rows, query]);

  const selected = selectedId ? rows.find((r) => r.id === selectedId) ?? null : null;

  function openNew() {
    setSelectedId(null);
    setDraft(emptyDraft(identity.name));
    setCreating(true);
  }

  function openRecord(r: Orbit2InternalRequest) {
    setCreating(false);
    setSelectedId(r.id);
    setDraft({ ...r, assigned_team: r.assigned_team ?? [] });
  }

  function cancel() {
    setCreating(false);
    if (selected) setDraft({ ...selected, assigned_team: selected.assigned_team ?? [] });
    else { setSelectedId(null); setDraft(emptyDraft(identity.name)); }
  }

  /** The row as it goes to the database — Task ID is never sent, it is generated. */
  function payload(d: Draft) {
    return {
      department: d.department,
      status: d.status ?? "Assigned",
      description: (d.description ?? "").trim(),
      assigned_team: d.assigned_team ?? [],
      requestor_name: d.requestor_name?.trim() || null,
      request_date: d.request_date || null,
      location: d.location?.trim() || null,
    };
  }

  async function submit() {
    if (!draft.department) { toast.error("Department is required."); return; }
    if (!draft.description?.trim()) { toast.error("Description is required."); return; }
    setSaving(true);
    try {
      if (creating) {
        const { data, error } = await sb
          .from("orbit2_internal_requests")
          .insert({ ...payload(draft), created_by: user?.id ?? null })
          .select("*")
          .single();
        if (error) throw error;
        toast.success(`${data.task_id} created`);
        await reload();
        setCreating(false);
        setSelectedId(data.id);
        setDraft({ ...(data as Orbit2InternalRequest), assigned_team: data.assigned_team ?? [] });
      } else if (selected) {
        const { error } = await sb.from("orbit2_internal_requests").update(payload(draft)).eq("id", selected.id);
        if (error) throw error;
        toast.success(`${selected.task_id} saved`);
        await reload();
      }
    } catch (e) {
      toast.error(errorMessage(e, "Could not save"));
    } finally {
      setSaving(false);
    }
  }

  /** Status straight from the table, without opening the record. */
  async function setStatus(r: Orbit2InternalRequest, status: string) {
    const { error } = await sb.from("orbit2_internal_requests").update({ status }).eq("id", r.id);
    if (error) { toast.error(errorMessage(error, "Could not change status")); return; }
    await reload();
    if (selectedId === r.id) setDraft((d) => ({ ...d, status }));
  }

  /** Admin-only, and the database enforces the same rule (orbit2_guard_delete). */
  async function deleteRecord(r: Orbit2InternalRequest) {
    if (!confirm(`Delete ${r.task_id} (${r.department})?\n\nThis cannot be undone.`)) return;
    const { error } = await sb.from("orbit2_internal_requests").delete().eq("id", r.id);
    if (error) { toast.error(errorMessage(error, "Could not delete")); return; }
    toast.success(`${r.task_id} deleted`);
    setSelectedId(null);
    setCreating(false);
    await reload();
  }

  if (loading) {
    return <div className="flex h-64 items-center justify-center"><Loader2 className="h-5 w-5 animate-spin text-muted-foreground" /></div>;
  }

  return (
    <div className="flex h-full min-h-0 flex-col">
      {/* ── Search + New ── */}
      <div className="flex items-center justify-between gap-3 border-b border-border/50 px-5 py-3">
        <p className="text-[15px] text-muted-foreground">
          {rows.length === 0
            ? "No internal requests yet."
            : `${filtered.length} of ${rows.length} request${rows.length === 1 ? "" : "s"}`}
        </p>
        <div className="flex items-center gap-2">
          <div className="relative">
            <Search className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <input className={cn(inputCls, "h-9 w-56 py-1 pl-8 text-[15px]")} placeholder="Search"
              value={query} onChange={(e) => setQuery(e.target.value)} />
          </div>
          <button onClick={openNew}
            className="flex h-9 items-center gap-1.5 rounded-md bg-primary px-3 text-[15px] font-medium text-primary-foreground hover:opacity-90">
            <Plus className="h-4 w-4" /> New Request
          </button>
        </div>
      </div>

      {/* ── Split screen ── */}
      <div className="grid min-h-0 flex-1 grid-cols-1 xl:grid-cols-[minmax(0,1.4fr)_minmax(420px,1fr)]">
        <div className="min-h-0 overflow-auto border-r border-border/50">
          <RequestTable rows={filtered} selectedId={selectedId} onOpen={openRecord} onStatus={setStatus} />
        </div>

        <div className="min-h-0 overflow-auto">
          {!creating && !selected ? (
            <div className="flex h-full flex-col items-center justify-center gap-2 px-8 text-center">
              <p className="text-[15px] font-semibold">No request selected</p>
              <p className="max-w-xs text-[14px] text-muted-foreground">
                Pick a Task ID on the left to see it in full, or start a new one.
              </p>
            </div>
          ) : (
            <DetailPanel
              creating={creating}
              draft={draft}
              setDraft={setDraft}
              selected={selected}
              saving={saving}
              locationOptions={locationOptions}
              onSubmit={submit}
              onCancel={cancel}
              onDelete={identity.isAdmin ? deleteRecord : undefined}
            />
          )}
        </div>
      </div>
    </div>
  );
}

// ── Left: the data table ────────────────────────────────────────────────────

function RequestTable({
  rows, selectedId, onOpen, onStatus,
}: {
  rows: Orbit2InternalRequest[];
  selectedId: string | null;
  onOpen: (r: Orbit2InternalRequest) => void;
  onStatus: (r: Orbit2InternalRequest, status: string) => void;
}) {
  const cols = ["Task ID", "Department", "Status", "Description", "Assigned Team", "Requestor", "Date", "Location"];

  if (rows.length === 0) {
    return (
      <div className="flex h-full items-center justify-center px-8 text-center text-[15px] text-muted-foreground">
        Nothing to show — requests appear here as they are logged.
      </div>
    );
  }

  return (
    <table className="w-full border-separate border-spacing-0 text-[14px]">
      <thead className="sticky top-0 z-10">
        <tr>
          {cols.map((c) => (
            <th key={c} className="whitespace-nowrap border-b border-border bg-muted/40 px-3 py-2.5 text-left font-semibold text-muted-foreground backdrop-blur">
              {c}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((r) => (
          <tr key={r.id} onClick={() => onOpen(r)}
            className={cn("cursor-pointer align-top transition",
              selectedId === r.id ? "bg-primary/10" : "hover:bg-muted/30")}>
            <td className="whitespace-nowrap border-b border-border/40 px-3 py-2 font-semibold text-primary">{r.task_id}</td>
            <td className="whitespace-nowrap border-b border-border/40 px-3 py-2">{r.department}</td>
            <td className="border-b border-border/40 px-3 py-2" onClick={(e) => e.stopPropagation()}>
              <IntReqStatusSelect value={r.status} onChange={(s) => onStatus(r, s)} />
            </td>
            <td className="max-w-[18rem] border-b border-border/40 px-3 py-2 text-muted-foreground">
              <span className="line-clamp-2">{r.description || "—"}</span>
            </td>
            <td className="border-b border-border/40 px-3 py-2">
              {(r.assigned_team ?? []).length === 0
                ? <span className="text-muted-foreground">—</span>
                : <span className="text-foreground/85">{r.assigned_team.join(", ")}</span>}
            </td>
            <td className="border-b border-border/40 px-3 py-2 text-muted-foreground">{r.requestor_name ?? "—"}</td>
            <td className="whitespace-nowrap border-b border-border/40 px-3 py-2 text-muted-foreground">{fmtDMY(r.request_date)}</td>
            <td className="border-b border-border/40 px-3 py-2 text-muted-foreground">{r.location ?? "—"}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** The status dropdown, colour-coded. */
function IntReqStatusSelect({
  value, onChange, className,
}: { value: string; onChange: (v: string) => void; className?: string }) {
  const c = intreqColor(value);
  return (
    <select
      value={value}
      onChange={(e) => { if (e.target.value !== value) onChange(e.target.value); }}
      className={cn("w-full min-w-[9rem] rounded-md border px-2 py-1 text-[14px] font-medium outline-none", className)}
      style={{ borderColor: `${c}66`, background: `${c}1A`, color: c }}
    >
      {INTREQ_STATUSES.map((s) => (
        <option key={s} value={s} className="bg-background text-foreground">{s}</option>
      ))}
    </select>
  );
}

// ── Right: the detail panel ─────────────────────────────────────────────────

function DetailPanel({
  creating, draft, setDraft, selected, saving, locationOptions, onSubmit, onCancel, onDelete,
}: {
  creating: boolean;
  draft: Draft;
  setDraft: React.Dispatch<React.SetStateAction<Draft>>;
  selected: Orbit2InternalRequest | null;
  saving: boolean;
  locationOptions: string[];
  onSubmit: () => void;
  onCancel: () => void;
  /** Present only for an Orbit 2 admin. */
  onDelete?: (r: Orbit2InternalRequest) => void;
}) {
  const set = <K extends keyof Draft>(k: K, v: Draft[K]) => setDraft((d) => ({ ...d, [k]: v }));

  return (
    <div className="space-y-4 p-5">
      {/* Task ID — generated, read-only, always the first thing on the panel. */}
      <div className="flex items-start justify-between gap-3 rounded-lg border border-border bg-muted/20 px-3.5 py-2.5">
        <div>
          <div className="text-[14px] text-muted-foreground">Task ID</div>
          <div className="font-display text-[22px] font-bold tracking-tight">
            {creating ? <span className="text-muted-foreground">Generated on submit</span> : selected?.task_id}
          </div>
        </div>
        <div className="w-44">
          <div className="mb-1 text-[14px] text-muted-foreground">Status</div>
          <IntReqStatusSelect value={draft.status ?? "Assigned"} onChange={(v) => set("status", v)} />
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-2">
        <Field label="Department">
          <select className={inputCls} value={draft.department ?? ""}
            onChange={(e) => set("department", e.target.value)}>
            <option value="" disabled>Choose a department</option>
            {INTREQ_DEPARTMENTS.map((d) => <option key={d} value={d}>{d}</option>)}
          </select>
        </Field>

        <Field label="Requestor">
          <input className={inputCls} value={draft.requestor_name ?? ""}
            onChange={(e) => set("requestor_name", e.target.value)} />
        </Field>

        <Field label="Description" className="sm:col-span-2">
          <textarea className={cn(inputCls, "min-h-[96px] resize-y")} value={draft.description ?? ""}
            onChange={(e) => set("description", e.target.value)}
            placeholder="What is being asked for" />
        </Field>

        <Field label="Date" hint={draft.request_date ? fmtDMY(draft.request_date) : undefined}>
          <input className={inputCls} type="date" value={draft.request_date ?? ""}
            onChange={(e) => set("request_date", e.target.value || null)} />
        </Field>

        <Field label="Location">
          <Typeahead value={draft.location ?? ""} onChange={(v) => set("location", v)}
            options={locationOptions} placeholder="Office, warehouse or berth" />
        </Field>

        <Field label="Assigned Team" className="sm:col-span-2">
          <TeamPicker value={draft.assigned_team ?? []} onChange={(v) => set("assigned_team", v)} />
        </Field>
      </div>

      {selected && !creating && (
        <div className="rounded-md border border-border bg-muted/10 px-3 py-2 text-[14px] text-muted-foreground">
          Logged {stamp(selected.created_at)}
          {selected.updated_at !== selected.created_at && <> · last changed {stamp(selected.updated_at)}</>}
        </div>
      )}

      {/* ── Form actions ── */}
      <div className="flex items-center justify-between gap-2 border-t border-border/50 pt-3">
        {selected && !creating && onDelete ? (
          <button onClick={() => onDelete(selected)} disabled={saving}
            className="flex items-center gap-1.5 rounded-md border border-destructive/40 px-3 py-2 text-[15px] font-medium text-destructive hover:bg-destructive/10 disabled:opacity-50">
            <Trash2 className="h-4 w-4" /> Delete
          </button>
        ) : <span />}
        <div className="flex gap-2">
          <button onClick={onCancel} disabled={saving}
            className="rounded-md bg-[#E05252] px-5 py-2 text-[15px] font-semibold text-white hover:opacity-90 disabled:opacity-50">
            Cancel
          </button>
          <button onClick={onSubmit} disabled={saving}
            className="flex items-center gap-1.5 rounded-md bg-[#3FA76A] px-5 py-2 text-[15px] font-semibold text-white hover:opacity-90 disabled:opacity-50">
            {saving && <Loader2 className="h-4 w-4 animate-spin" />} Submit
          </button>
        </div>
      </div>
    </div>
  );
}
